const lastFeedbackByDirection = {
 TOO_LOW: { key: '', message: '' },
 TOO_HIGH: { key: '', message: '' }
};
function chooseFeedback(pool,prefix,fallbackKeys,fallbackTexts,direction,key){
 const cache=lastFeedbackByDirection[direction];
 if(!cache)return fallbackTexts[0];
 if(cache.key===key&&cache.message)return cache.message;
 const provided=Array.isArray(pool)?pool.filter(value=>typeof value==='string'&&value.trim()):[];
 const localized=Array.from({length:30},(_,index)=>uiText(prefix+index,'')).filter(value=>value&&value!==prefix);
 const fallback=fallbackKeys.map((translationKey,index)=>uiText(translationKey,fallbackTexts[index]));
 const messages=localized.length?localized:(provided.length?provided:fallback);
 const alternatives=messages.filter(message=>message!==cache.message);
 const choices=alternatives.length?alternatives:messages;
 const chosen=choices[Math.floor(Math.random()*choices.length)]||fallbackTexts[0];
 cache.message=chosen;cache.key=key;
 return chosen;
}
