 const relics=Array.isArray(s.relicInventory)?s.relicInventory:[],equipped=Array.isArray(s.equippedRelicIds)?s.equippedRelicIds:[];
 setText($('relicCount'),`${equipped.length} / 4 EQUIPPED`);
 const relicList=$('relicList');if(relicList){relicList.replaceChildren();for(const [id,name,description] of relicDefinitions){const owned=relics.includes(id),active=equipped.includes(id);const card=document.createElement('article');card.className='catalog-entry';const copy=document.createElement('div');copy.className='catalog-entry-copy';const title=document.createElement('strong');title.textContent=name;const detail=document.createElement('span');detail.textContent=description;copy.append(title,detail);const button=document.createElement('button');button.type='button';button.className='world-action-button';button.dataset.bridgeAction='relic';button.dataset.relicId=id;button.dataset.relicAction=active?'unequip':'equip';button.disabled=!!pending||!owned||(!active&&equipped.length>=4);button.textContent=!owned?'Defeat boss to earn':active?'Unequip':'Equip';card.append(copy,button);relicList.appendChild(card)}}
 const entries=Array.isArray(s.codexEntries)?s.codexEntries:[],found=codexDefinitions.filter(([id])=>entries.includes(id)).length;
 setText($('codexCount'),`${found} / ${codexDefinitions.length}`);if($('codexProgressFill'))$('codexProgressFill').style.width=`${found/codexDefinitions.length*100}%`;
 const codexList=$('codexList');if(codexList){codexList.replaceChildren();for(const [id,name] of codexDefinitions){const card=document.createElement('article');card.className='catalog-entry';const copy=document.createElement('div');copy.className='catalog-entry-copy';const title=document.createElement('strong');title.textContent=name;const detail=document.createElement('span');detail.textContent=entries.includes(id)?'Discovered':'Undiscovered · keep exploring';copy.append(title,detail);card.appendChild(copy);codexList.appendChild(card)}}
 const reward=$('claimCodexReward');if(reward){reward.disabled=!!pending||found!==codexDefinitions.length||!!s.codexRewardClaimed;reward.textContent=s.codexRewardClaimed?'Completion reward claimed':'Claim 100 Nebula';}
