function renderTraitLoadout(s){
 const root=$('traitsList');if(!root)return;
 const traits=Array.isArray(s.gameplayTraits)?s.gameplayTraits:[];
 root.replaceChildren();
 setText($('traitsSummary'),uiText('traits_summary_format','%s of %s gameplay traits active · progress unlocks more',traits.filter(t=>t.active).length,traits.length));
 if(!traits.length){const empty=document.createElement('p');empty.className='catalog-empty';empty.textContent=uiText('traits_empty','No gameplay trait data is available yet.');root.appendChild(empty);return}
 for(const trait of traits){
  const card=document.createElement('article');card.className='trait-entry'+(trait.active?' is-active':' is-locked');
  const copy=document.createElement('div');copy.className='catalog-entry-copy';
  const title=document.createElement('strong');title.textContent=String(trait.title||trait.id||'Gameplay trait');
  const description=document.createElement('span');description.textContent=String(trait.description||'');
  const status=document.createElement('span');status.className='trait-status';const remainingCorrectGuesses=Math.max(0,Number(trait.requiredCorrectGuesses||0)-Number(s.correctGuesses||0));status.textContent=trait.active?uiText('traits_active','ACTIVE'):uiText('traits_locked_format','LOCKED · %s correct guesses',remainingCorrectGuesses);
  copy.append(title,description,status);card.appendChild(copy);
  const arms=Array.isArray(trait.arms)?trait.arms:[];
  if(arms.length){const label=document.createElement('p');label.className='trait-arm-label';label.textContent=uiText('traits_choose_variant','Choose a gameplay variant');card.appendChild(label);const list=document.createElement('div');list.className='trait-arm-list';
   for(const arm of arms){const button=document.createElement('button');button.type='button';button.className='trait-arm-button'+(arm.id===trait.selectedArm?' is-selected':'');button.dataset.bridgeAction='trait-arm';button.dataset.traitId=trait.id;button.dataset.armId=arm.id;button.setAttribute('aria-pressed',String(arm.id===trait.selectedArm));const armTitle=document.createElement('strong');armTitle.textContent=String(arm.label||arm.id);const armDescription=document.createElement('span');armDescription.textContent=String(arm.description||'');button.append(armTitle,armDescription);button.disabled=!!pending||!trait.active||arm.id===trait.selectedArm;list.appendChild(button)}
   card.appendChild(list);
  }else{const note=document.createElement('p');note.className='trait-arm-label';note.textContent=trait.active?uiText('traits_automatic','This trait applies its gameplay rule automatically.'):uiText('traits_unlock_hint','Unlock this trait to activate its rule.');card.appendChild(note)}
  root.appendChild(card)
 }
}
