function startFeatureTutorial(id){
 if(!id||featureTutorialId!==id||!lastState||['settings','about','more','play'].includes(id))return;
 const definition=featureTutorialDefinitions[id];if(!definition)return;
 featureTutorialSteps=definition.steps.filter(([target])=>!!document.querySelector(target)).map(([target,title,body,bodyFallback])=>({target,title,body,titleFallback:featureTutorialTitleFallbacks[id]||'Feature tour',bodyFallback}));
 if(!featureTutorialSteps.length)return;
 nimmyStepIndex=0;nimmyTutorialStarted=true;
 const root=$('nimmyTutorial');if(root)root.hidden=false;
 renderFeatureTutorialStep();
}
function renderFeatureTutorialStep(){
 const step=featureTutorialSteps[nimmyStepIndex];if(!step)return;
 setText($('nimmyName'),uiText('nimmy_name','Nimmy'));
 setText($('nimmyStep'),uiText('nimmy_step_counter','Step %s of %s').replace('%s',String(nimmyStepIndex+1)).replace('%s',String(featureTutorialSteps.length)));
 setText($('nimmyTitle'),uiText(step.title,step.titleFallback));
 setText($('nimmyBody'),uiText(step.body,step.bodyFallback));
 setText($('nimmyNext'),nimmyStepIndex===featureTutorialSteps.length-1?uiText('nimmy_finish','Let’s go!'):uiText('nimmy_next','Next'));
 setText($('nimmySkip'),uiText('nimmy_skip','Skip tour'));
 updateNimmySpotlight();
}
